def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Post-order traversal (children before parent)
    order = []
    stack = [0]
    while stack:
        v = stack.pop()
        order.append(v)
        for u in children[v]:
            stack.append(u)
    order.reverse()

    # Compute subtree demands and whether a subtree contains a critical node
    sub_demand = [0] * n
    has_crit = [False] * n
    for v in order:
        sub_demand[v] = demand[v]
        has_crit[v] = critical[v]
        for u in children[v]:
            sub_demand[v] += sub_demand[u]
            has_crit[v] = has_crit[v] or has_crit[u]

    INF = 10**18
    dp = [None] * n          # dp[v][L] = min modified cost for subtree v, load L, v retained

    for v in order:
        cap_v = cap[v] if v >= 1 else root_cap
        max_load_v = min(sub_demand[v], cap_v)

        if demand[v] > max_load_v:
            dp_v = [INF] * (max_load_v + 1)
        else:
            dp_v = [INF] * (max_load_v + 1)
            dp_v[demand[v]] = -penalty * demand[v]   # retain v alone

            for u in children[v]:
                # Collect all options for child u
                max_load_u = len(dp[u]) - 1
                opt_arr = [INF] * (max_load_u + 1)
                if not has_crit[u]:                     # cut edge above u
                    if cut_cost[u] < opt_arr[0]:
                        opt_arr[0] = cut_cost[u]
                for L_u, cost_u in enumerate(dp[u]):    # keep edge above u
                    if cost_u < opt_arr[L_u]:
                        opt_arr[L_u] = cost_u
                options = [(L, c) for L, c in enumerate(opt_arr) if c < INF]

                if not options:                         # u cannot be kept nor cut
                    dp_v = [INF] * (max_load_v + 1)
                    break

                # Merge options into dp_v (knapsack, small-to-large)
                new_dp = [INF] * (max_load_v + 1)
                curr = [(L, dp_v[L]) for L in range(max_load_v + 1) if dp_v[L] < INF]
                if len(curr) < len(options):
                    for L, c in curr:
                        for L_u, c_u in options:
                            if L + L_u <= max_load_v:
                                if c + c_u < new_dp[L + L_u]:
                                    new_dp[L + L_u] = c + c_u
                else:
                    for L_u, c_u in options:
                        for L, c in curr:
                            if L + L_u <= max_load_v:
                                if c + c_u < new_dp[L + L_u]:
                                    new_dp[L + L_u] = c + c_u
                dp_v = new_dp
        dp[v] = dp_v

    # Root must be retained; check feasibility
    if all(c == INF for c in dp[0]):
        return None
    min_mod = min(c for c in dp[0] if c < INF)
    total_demand = sub_demand[0]
    return min_mod + penalty * total_demand

def run_lock_manager(ops):
    log = []
    txs = {}          # tx_id -> {'state': 'ACTIVE'/'WAITING'/'FINISHED', 'held': {}, 'waiting': None}
    resources = {}   # res -> {'holders': {}, 'queue': [], 'waiting_holders': set()}
    waiting_set = set()

    def get_tx(tx):
        if tx not in txs:
            txs[tx] = {'state': 'ACTIVE', 'held': {}, 'waiting': None}
        return txs[tx]

    def get_res(res):
        if res not in resources:
            resources[res] = {'holders': {}, 'queue': [], 'waiting_holders': set()}
        return resources[res]

    def is_compatible(mode1, mode2):
        return mode1 == 'S' and mode2 == 'S'

    def process_queue(res, i):
        r = resources[res]
        while r['queue']:
            front_tx, front_mode = r['queue'][0]
            holders = r['holders']
            # check grantability
            if front_mode == 'S':
                grantable = True
                for h, mode in holders.items():
                    if h != front_tx and mode == 'X':
                        grantable = False
                        break
            else:  # 'X'
                grantable = True
                for h in holders:
                    if h != front_tx:
                        grantable = False
                        break
            if not grantable:
                break
            # grant
            r['queue'].pop(0)
            tx = txs[front_tx]
            waiting_set.discard(front_tx)
            for r_res in tx['held']:
                resources[r_res]['waiting_holders'].discard(front_tx)
            if res in tx['held'] and tx['held'][res] == 'S':
                # upgrade
                tx['held'][res] = 'X'
                holders[front_tx] = 'X'
            else:
                tx['held'][res] = front_mode
                holders[front_tx] = front_mode
            tx['state'] = 'ACTIVE'
            tx['waiting'] = None
            log.append(("GRANT", i, front_tx, res, front_mode))

    def release(tx, i):
        t = txs[tx]
        affected = set()
        # remove queued request
        if t['waiting'] is not None:
            res, mode = t['waiting']
            r = resources[res]
            for idx, (q_tx, q_mode) in enumerate(r['queue']):
                if q_tx == tx:
                    r['queue'].pop(idx)
                    break
            t['waiting'] = None
            waiting_set.discard(tx)
            affected.add(res)
        # drop held locks
        for res in list(t['held'].keys()):
            r = resources[res]
            del r['holders'][tx]
            r['waiting_holders'].discard(tx)
            affected.add(res)
        t['held'] = {}
        t['state'] = 'FINISHED'
        # process affected resources in ascending order
        for res in sorted(affected):
            process_queue(res, i)

    def find_cycles():
        if not waiting_set:
            return set()
        graph = {}
        for tx in waiting_set:
            res, mode = txs[tx]['waiting']
            r = resources[res]
            edges = set()
            # edges to waiting holders
            for h in r['waiting_holders']:
                if h == tx:
                    continue
                if mode == 'S':
                    if r['holders'][h] == 'X':
                        edges.add(h)
                else:  # 'X'
                    edges.add(h)
            # edges to queued ahead
            queue = r['queue']
            for idx, (q_tx, q_mode) in enumerate(queue):
                if q_tx == tx:
                    for j in range(idx):
                        if queue[j][0] in waiting_set:
                            edges.add(queue[j][0])
                    break
            graph[tx] = list(edges)

        # Tarjan's SCC (iterative)
        index = 0
        indices = {}
        lowlink = {}
        on_stack = set()
        stack = []
        sccs = []

        for start in waiting_set:
            if start in indices:
                continue
            call_stack = [(start, 0)]
            while call_stack:
                node, idx = call_stack[-1]
                if idx == 0:
                    indices[node] = index
                    lowlink[node] = index
                    index += 1
                    stack.append(node)
                    on_stack.add(node)
                if idx < len(graph[node]):
                    neighbor = graph[node][idx]
                    call_stack[-1] = (node, idx + 1)
                    if neighbor not in indices:
                        call_stack.append((neighbor, 0))
                    elif neighbor in on_stack:
                        lowlink[node] = min(lowlink[node], indices[neighbor])
                else:
                    if lowlink[node] == indices[node]:
                        scc = []
                        while True:
                            w = stack.pop()
                            on_stack.remove(w)
                            scc.append(w)
                            if w == node:
                                break
                        sccs.append(scc)
                    call_stack.pop()
                    if call_stack:
                        parent = call_stack[-1][0]
                        lowlink[parent] = min(lowlink[parent], lowlink[node])

        cycle_nodes = set()
        for scc in sccs:
            if len(scc) > 1:
                cycle_nodes.update(scc)
        return cycle_nodes

    for i, op in enumerate(ops):
        if op[0] == "COMMIT":
            tx = op[1]
            t = get_tx(tx)
            if t['state'] in ('WAITING', 'FINISHED'):
                log.append(("IGNORED", i, tx))
                continue
            log.append(("COMMIT", i, tx))
            release(tx, i)
            # fall through to deadlock check
        else:
            mode = op[0]
            tx = op[1]
            res = op[2]
            t = get_tx(tx)
            if t['state'] in ('WAITING', 'FINISHED'):
                log.append(("IGNORED", i, tx))
                continue
            r = get_res(res)
            if res in t['held']:
                held_mode = t['held'][res]
                if held_mode == 'X' or (held_mode == 'S' and mode == 'S'):
                    log.append(("HELD", i, tx, res))
                    continue
                elif held_mode == 'S' and mode == 'X':
                    # upgrade
                    if len(r['holders']) == 1 and tx in r['holders']:
                        t['held'][res] = 'X'
                        r['holders'][tx] = 'X'
                        log.append(("GRANT", i, tx, res, "X"))
                        # fall through to deadlock check
                    else:
                        queue = r['queue']
                        last_upgrade_idx = -1
                        for idx, (q_tx, q_mode) in enumerate(queue):
                            if q_mode == 'X' and res in txs[q_tx]['held'] and txs[q_tx]['held'][res] == 'S':
                                last_upgrade_idx = idx
                        if last_upgrade_idx == -1:
                            insert_idx = 0
                        else:
                            insert_idx = last_upgrade_idx + 1
                        queue.insert(insert_idx, (tx, 'X'))
                        t['state'] = 'WAITING'
                        t['waiting'] = (res, 'X')
                        waiting_set.add(tx)
                        for r_res in t['held']:
                            resources[r_res]['waiting_holders'].add(tx)
                        log.append(("WAIT", i, tx, res, "X"))
                        # fall through to deadlock check
                else:
                    pass  # should not happen
            else:
                # T holds nothing on R
                if not r['queue'] and all(is_compatible(mode, h_mode) for h_mode in r['holders'].values()):
                    t['held'][res] = mode
                    r['holders'][tx] = mode
                    log.append(("GRANT", i, tx, res, mode))
                    # fall through to deadlock check
                else:
                    r['queue'].append((tx, mode))
                    t['state'] = 'WAITING'
                    t['waiting'] = (res, mode)
                    waiting_set.add(tx)
                    for r_res in t['held']:
                        resources[r_res]['waiting_holders'].add(tx)
                    log.append(("WAIT", i, tx, res, mode))
                    # fall through to deadlock check

        # Deadlock detection and resolution
        if waiting_set:
            while True:
                cycle_nodes = find_cycles()
                if not cycle_nodes:
                    break
                victim = max(cycle_nodes)
                log.append(("ABORT", i, victim))
                release(victim, i)

    return log

import re

_KEY_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_-]*\Z')
_INT_RE = re.compile(r'-?(0|[1-9][0-9]*)\Z')


def _convert_scalar(text):
    if text[0] == '"':
        n = len(text)
        i = 1
        chars = []
        while i < n:
            c = text[i]
            if c == '\\':
                if i + 1 >= n:
                    return ("error", "bad escape")
                nxt = text[i + 1]
                if nxt == '\\':
                    chars.append('\\')
                elif nxt == '"':
                    chars.append('"')
                elif nxt == 'n':
                    chars.append('\n')
                elif nxt == 't':
                    chars.append('\t')
                else:
                    return ("error", "bad escape")
                i += 2
            elif c == '"':
                if i != n - 1:
                    return ("error", "bad string")
                return ("ok", ''.join(chars))
            else:
                chars.append(c)
                i += 1
        return ("error", "bad string")
    if text == "true":
        return ("ok", True)
    if text == "false":
        return ("ok", False)
    if text == "null":
        return ("ok", None)
    if _INT_RE.match(text):
        return ("ok", int(text))
    return ("ok", text)


def parse_outline(text: str) -> tuple:
    lines = text.split("\n")
    stack = []  # each frame: [indent, kind, container, pending]
    root = None

    for line_no, line in enumerate(lines, 1):
        # compute lead (spaces/tabs) and rest
        i = 0
        n = len(line)
        while i < n and (line[i] == ' ' or line[i] == '\t'):
            i += 1
        lead = line[:i]
        rest = line[i:]

        if rest == '' or rest[0] == '#':
            continue

        indent = len(lead)

        if '\t' in lead:
            return ("error", line_no, "tab in indentation")

        is_item = False
        is_opener = False
        key = None
        scalar_text = None

        if rest == '-' or rest.startswith('- '):
            is_item = True
            text = rest[2:].strip(' ')
            if text == '':
                is_opener = True
            else:
                scalar_text = text
        else:
            colon_idx = rest.find(':')
            if colon_idx == -1:
                return ("error", line_no, "invalid entry")
            key_part = rest[:colon_idx]
            if not _KEY_RE.match(key_part):
                return ("error", line_no, "invalid entry")
            after = rest[colon_idx + 1:]
            if after == '' or after.strip(' ') == '':
                is_opener = True
                key = key_part
            else:
                if after[0] != ' ':
                    return ("error", line_no, "invalid entry")
                scalar_text = after.strip(' ')
                key = key_part

        value = None
        if not is_opener:
            res = _convert_scalar(scalar_text)
            if res[0] == "error":
                return ("error", line_no, res[1])
            value = res[1]

        if not stack:
            if indent != 0:
                return ("error", line_no, "unexpected indent")
            root = [] if is_item else {}
            stack.append([indent, 'list' if is_item else 'map', root, None])
            top = stack[-1]
            if is_opener:
                if is_item:
                    top[2].append(None)
                    top[3] = len(top[2]) - 1
                else:
                    top[2][key] = None
                    top[3] = key
            else:
                if is_item:
                    top[2].append(value)
                else:
                    top[2][key] = value
        else:
            top = stack[-1]
            if top[3] is not None and indent > top[0]:
                # new nested block
                new_container = [] if is_item else {}
                if top[1] == 'list':
                    top[2][top[3]] = new_container
                else:
                    top[2][top[3]] = new_container
                top[3] = None
                stack.append([indent, 'list' if is_item else 'map', new_container, None])
                top = stack[-1]
                if is_opener:
                    if is_item:
                        top[2].append(None)
                        top[3] = len(top[2]) - 1
                    else:
                        top[2][key] = None
                        top[3] = key
                else:
                    if is_item:
                        top[2].append(value)
                    else:
                        top[2][key] = value
            else:
                if top[3] is not None:
                    top[3] = None
                if indent > top[0]:
                    return ("error", line_no, "unexpected indent")
                while stack and stack[-1][0] > indent:
                    stack.pop()
                if not stack or stack[-1][0] != indent:
                    return ("error", line_no, "inconsistent dedent")
                top = stack[-1]
                line_kind = 'list' if is_item else 'map'
                if top[1] != line_kind:
                    return ("error", line_no, "mixed block")
                if not is_item and key in top[2]:
                    return ("error", line_no, "duplicate key '%s'" % key)
                if is_opener:
                    if is_item:
                        top[2].append(None)
                        top[3] = len(top[2]) - 1
                    else:
                        top[2][key] = None
                        top[3] = key
                else:
                    if is_item:
                        top[2].append(value)
                    else:
                        top[2][key] = value

    return ("ok", root)

def run_pile(src: str, max_steps: int) -> tuple:
    # ---------- Tokenization ----------
    tokens = []
    indices = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c == ' ' or c == '\t' or c == '\n' or c == '\r':
            i += 1
            continue
        if c == '[' or c == ']':
            tokens.append(c)
            indices.append(i)
            i += 1
            continue
        start = i
        while i < n and src[i] not in ' \t\n\r[]':
            i += 1
        tokens.append(src[start:i])
        indices.append(start)

    # ---------- Constants ----------
    INT = 0
    WORD = 1
    QUOTE = 2
    DEF = 3
    BUILTINS = {'dup', 'drop', 'swap', 'over', 'rot', '+', '-', '*', '/', '%',
                '<', '=', 'if', 'times', 'while', 'call', 'dip'}

    def is_int(s: str) -> bool:
        if s.startswith('-'):
            s = s[1:]
        return len(s) > 0 and all('0' <= c <= '9' for c in s)

    # ---------- Structure check & tree building ----------
    frames = [['top', []]]          # each frame: [type, ...]
    i = 0
    n = len(tokens)
    while i < n:
        token = tokens[i]
        idx = indices[i]
        if token == '[':
            frames.append(['quote', idx, []])
            i += 1
        elif token == ']':
            if not frames or frames[-1][0] != 'quote':
                return ("error", idx, "unmatched ]")
            qf = frames.pop()
            qe = (QUOTE, qf[1], qf[2])
            frames[-1][1].append(qe)
            i += 1
        elif token == ':':
            if len(frames) > 1:
                return ("error", idx, "misplaced :")
            if i == n - 1:
                return ("error", idx, "unclosed :")
            name_token = tokens[i + 1]
            name_idx = indices[i + 1]
            if (name_token in ('[', ']', ':', ';') or
                    is_int(name_token) or name_token in BUILTINS):
                return ("error", name_idx, "bad name")
            frames.append(['def', idx, name_token, name_idx, []])
            i += 2
        elif token == ';':
            if not frames or frames[-1][0] != 'def':
                return ("error", idx, "unmatched ;")
            df = frames.pop()
            de = (DEF, df[1], df[2], df[4])
            frames[-1][1].append(de)
            i += 1
        else:
            if is_int(token):
                elem = (INT, idx, token)
            else:
                elem = (WORD, idx, token)
            frames[-1][1].append(elem)
            i += 1

    if len(frames) > 1:
        earliest = min(frames[1:], key=lambda f: f[1])
        if earliest[0] == 'quote':
            return ("error", earliest[1], "unclosed [")
        else:
            return ("error", earliest[1], "unclosed :")

    top_level = frames[0][1]

    # ---------- Execution ----------
    SEQ = 0
    LOOP = 1
    WHILE = 2
    DIP = 3

    stack = []
    words = {}
    frames = [[SEQ, top_level, 0]]
    steps = 0

    def exec_element(elem):
        etype = elem[0]
        if etype == INT:
            stack.append(int(elem[2]))
        elif etype == QUOTE:
            stack.append(elem[2])
        elif etype == DEF:
            words[elem[2]] = elem[3]
        else:  # WORD
            name = elem[2]
            if name in BUILTINS:
                idx = elem[1]
                if name == 'dup':
                    if len(stack) < 1: return ("error", idx, "stack underflow")
                    stack.append(stack[-1])
                elif name == 'drop':
                    if len(stack) < 1: return ("error", idx, "stack underflow")
                    stack.pop()
                elif name == 'swap':
                    if len(stack) < 2: return ("error", idx, "stack underflow")
                    b = stack.pop(); a = stack.pop()
                    stack.append(b); stack.append(a)
                elif name == 'over':
                    if len(stack) < 2: return ("error", idx, "stack underflow")
                    stack.append(stack[-2])
                elif name == 'rot':
                    if len(stack) < 3: return ("error", idx, "stack underflow")
                    c = stack.pop(); b = stack.pop(); a = stack.pop()
                    stack.append(b); stack.append(c); stack.append(a)
                elif name in ('+', '-', '*', '/', '%', '<', '='):
                    if len(stack) < 2: return ("error", idx, "stack underflow")
                    b = stack.pop(); a = stack.pop()
                    if not (isinstance(a, int) and isinstance(b, int)):
                        return ("error", idx, "type error")
                    if name == '+': stack.append(a + b)
                    elif name == '-': stack.append(a - b)
                    elif name == '*': stack.append(a * b)
                    elif name == '/':
                        if b == 0: return ("error", idx, "division by zero")
                        stack.append(a // b)
                    elif name == '%':
                        if b == 0: return ("error", idx, "division by zero")
                        stack.append(a % b)
                    elif name == '<': stack.append(1 if a < b else 0)
                    elif name == '=': stack.append(1 if a == b else 0)
                elif name == 'if':
                    if len(stack) < 3: return ("error", idx, "stack underflow")
                    f = stack.pop(); t = stack.pop(); c = stack.pop()
                    if not isinstance(c, int): return ("error", idx, "type error")
                    if not (isinstance(t, list) and isinstance(f, list)):
                        return ("error", idx, "type error")
                    body = t if c != 0 else f
                    frames.append([SEQ, body, 0])
                elif name == 'times':
                    if len(stack) < 2: return ("error", idx, "stack underflow")
                    n = stack.pop(); q = stack.pop()
                    if not (isinstance(q, list) and isinstance(n, int)):
                        return ("error", idx, "type error")
                    if n < 0: return ("error", idx, "negative count")
                    if n > 0 and len(q) > 0:
                        frames.append([LOOP, q, n, 0])
                elif name == 'while':
                    if len(stack) < 2: return ("error", idx, "stack underflow")
                    b = stack.pop(); c = stack.pop()
                    if not (isinstance(c, list) and isinstance(b, list)):
                        return ("error", idx, "type error")
                    frames.append([WHILE, c, b, 0, 0, idx])
                elif name == 'call':
                    if len(stack) < 1: return ("error", idx, "stack underflow")
                    q = stack.pop()
                    if not isinstance(q, list): return ("error", idx, "type error")
                    frames.append([SEQ, q, 0])
                elif name == 'dip':
                    if len(stack) < 2: return ("error", idx, "stack underflow")
                    q = stack.pop(); a = stack.pop()
                    if not isinstance(q, list): return ("error", idx, "type error")
                    frames.append([DIP, a, q, 0])
            elif name in words:
                frames.append([SEQ, words[name], 0])
            else:
                return ("error", elem[1], f"unknown word '{name}'")
        return None

    while frames:
        frame = frames[-1]
        ftype = frame[0]
        if ftype == SEQ:
            elements, idx = frame[1], frame[2]
            if idx >= len(elements):
                frames.pop()
                continue
            elem = elements[idx]
            frame[2] = idx + 1
            steps += 1
            if steps > max_steps:
                return ("error", elem[1], "step limit exceeded")
            err = exec_element(elem)
            if err: return err
        elif ftype == LOOP:
            body, remaining, idx = frame[1], frame[2], frame[3]
            if idx >= len(body):
                if remaining > 1:
                    frame[2] = remaining - 1
                    frame[3] = 0
                    continue
                else:
                    frames.pop()
                    continue
            elem = body[idx]
            frame[3] = idx + 1
            steps += 1
            if steps > max_steps:
                return ("error", elem[1], "step limit exceeded")
            err = exec_element(elem)
            if err: return err
        elif ftype == WHILE:
            cond_body, body_body, phase, idx, while_idx = frame[1], frame[2], frame[3], frame[4], frame[5]
            if phase == 0:
                if idx >= len(cond_body):
                    if len(stack) < 1:
                        return ("error", while_idx, "stack underflow")
                    v = stack.pop()
                    if not isinstance(v, int):
                        return ("error", while_idx, "type error")
                    if v != 0:
                        frame[3] = 1
                        frame[4] = 0
                        continue
                    else:
                        frames.pop()
                        continue
                else:
                    elem = cond_body[idx]
                    frame[4] = idx + 1
                    steps += 1
                    if steps > max_steps:
                        return ("error", elem[1], "step limit exceeded")
                    err = exec_element(elem)
                    if err: return err
            else:  # phase == 1
                if idx >= len(body_body):
                    frame[3] = 0
                    frame[4] = 0
                    continue
                else:
                    elem = body_body[idx]
                    frame[4] = idx + 1
                    steps += 1
                    if steps > max_steps:
                        return ("error", elem[1], "step limit exceeded")
                    err = exec_element(elem)
                    if err: return err
        elif ftype == DIP:
            saved, body, idx = frame[1], frame[2], frame[3]
            if idx >= len(body):
                stack.append(saved)
                frames.pop()
                continue
            elem = body[idx]
            frame[3] = idx + 1
            steps += 1
            if steps > max_steps:
                return ("error", elem[1], "step limit exceeded")
            err = exec_element(elem)
            if err: return err

    # ---------- Convert stack to output format ----------
    def quote_to_list(body):
        res = []
        st = [(body, 0, res)]
        while st:
            elements, idx, target = st[-1]
            if idx >= len(elements):
                st.pop()
                continue
            elem = elements[idx]
            st[-1] = (elements, idx + 1, target)
            if elem[0] == INT:
                target.append(elem[2])
            elif elem[0] == WORD:
                target.append(elem[2])
            elif elem[0] == QUOTE:
                new_list = []
                target.append(new_list)
                st.append((elem[2], 0, new_list))
        return res

    out_stack = []
    for v in stack:
        if isinstance(v, int):
            out_stack.append(v)
        else:
            out_stack.append(quote_to_list(v))
    return ("ok", out_stack)

import sys
import random
from array import array

sys.setrecursionlimit(1000000)

def run_ops(ops):
    # Persistent treap arrays (1-indexed, 0 is the null node)
    val = array('i', [0])
    cnt = array('i', [0])
    prio = array('i', [0])
    left = array('i', [0])
    right = array('i', [0])
    size = array('i', [0])
    node_cnt = array('i', [0])

    def new_node(v, c, p, l=0, r=0):
        val.append(v)
        cnt.append(c)
        prio.append(p)
        left.append(l)
        right.append(r)
        size.append(c + size[l] + size[r])
        node_cnt.append(1 + node_cnt[l] + node_cnt[r])
        return len(val) - 1

    def split(t, key):
        if t == 0:
            return (0, 0)
        if val[t] < key:
            l, r = split(right[t], key)
            new_t = new_node(val[t], cnt[t], prio[t], left[t], l)
            return (new_t, r)
        else:
            l, r = split(left[t], key)
            new_t = new_node(val[t], cnt[t], prio[t], r, right[t])
            return (l, new_t)

    def merge(l, r):
        if l == 0 or r == 0:
            return l or r
        if prio[l] > prio[r]:
            new_right = merge(right[l], r)
            return new_node(val[l], cnt[l], prio[l], left[l], new_right)
        else:
            new_left = merge(l, left[r])
            return new_node(val[r], cnt[r], prio[r], new_left, right[r])

    def insert(root, x):
        left, right = split(root, x)
        mid, right = split(right, x + 1)
        if mid != 0:
            mid = new_node(val[mid], cnt[mid] + 1, prio[mid], left[mid], right[mid])
        else:
            mid = new_node(x, 1, random.randint(1, 1 << 30))
        return merge(merge(left, mid), right)

    def contains(root, x):
        t = root
        while t != 0:
            if val[t] == x:
                return True
            elif val[t] < x:
                t = right[t]
            else:
                t = left[t]
        return False

    def remove(root, x):
        left, right = split(root, x)
        mid, right = split(right, x + 1)
        if cnt[mid] > 1:
            mid = new_node(val[mid], cnt[mid] - 1, prio[mid], left[mid], right[mid])
        else:
            mid = 0
        return merge(merge(left, mid), right)

    def count_less(root, x):
        res = 0
        t = root
        while t != 0:
            if val[t] < x:
                res += cnt[t] + size[left[t]]
                t = right[t]
            else:
                t = left[t]
        return res

    def kth(root, k):
        t = root
        while t != 0:
            ls = size[left[t]]
            if k <= ls:
                t = left[t]
            elif k <= ls + cnt[t]:
                return val[t]
            else:
                k -= ls + cnt[t]
                t = right[t]
        return None

    def get_size(root):
        return size[root]

    def get_distinct(root):
        return node_cnt[root]

    # Checkpoint management
    current_root = 0
    checkpoint_roots = [0]      # 1-based, index 0 unused
    valid = [False]
    parent = [0]                # DSU for fast invalidation
    max_cp = 0

    def find(x):
        if x >= len(parent):
            return x
        root = x
        while parent[root] != root:
            root = parent[root]
        while x != root:
            nxt = parent[x]
            parent[x] = root
            x = nxt
        return root

    outputs = []
    for op in ops:
        cmd = op[0]
        if cmd == "add":
            x = op[1]
            current_root = insert(current_root, x)
            outputs.append(get_size(current_root))
        elif cmd == "remove":
            x = op[1]
            if contains(current_root, x):
                current_root = remove(current_root, x)
                outputs.append(True)
            else:
                outputs.append(False)
        elif cmd == "checkpoint":
            cp_id = len(checkpoint_roots)
            checkpoint_roots.append(current_root)
            valid.append(True)
            parent.append(cp_id)
            max_cp = cp_id
            outputs.append(cp_id)
        elif cmd == "rollback":
            c = op[1]
            if 1 <= c < len(checkpoint_roots) and valid[c]:
                current_root = checkpoint_roots[c]
                i = find(c + 1)
                while i <= max_cp:
                    valid[i] = False
                    parent[i] = find(i + 1)
                    i = find(i)
                outputs.append(get_size(current_root))
            else:
                outputs.append("BADCP")
        elif cmd == "median":
            s = get_size(current_root)
            if s == 0:
                outputs.append(None)
            else:
                k = (s + 1) // 2
                outputs.append(kth(current_root, k))
        elif cmd == "count_less":
            x = op[1]
            outputs.append(count_less(current_root, x))
        elif cmd == "distinct":
            outputs.append(get_distinct(current_root))

    return outputs

import heapq
from collections import OrderedDict


def run_cache(capacity, ops):
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> [value, expires_at or None]; most recently used at end
    expiry_heap = []  # min-heap of (expires_at, key)
    out = []
    last_t = None

    def purge_expired(t):
        while expiry_heap and expiry_heap[0][0] <= t:
            exp, key = heapq.heappop(expiry_heap)
            entry = store.get(key)
            if entry is not None and entry[1] == exp:
                del store[key]

    def alive(entry, t):
        return entry[1] is None or t < entry[1]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        purge_expired(t)

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (not isinstance(ttl, int) or ttl < 1):
                raise ValueError("ttl must be None or a positive int")
            expires_at = None if ttl is None else t + ttl
            entry = store.get(key)
            if entry is not None:
                # Key exists and is alive (purge_expired removed expired ones)
                entry[0] = value
                entry[1] = expires_at
                store.move_to_end(key)
                if expires_at is not None:
                    heapq.heappush(expiry_heap, (expires_at, key))
            else:
                if len(store) >= capacity:
                    store.popitem(last=False)
                store[key] = [value, expires_at]
                if expires_at is not None:
                    heapq.heappush(expiry_heap, (expires_at, key))

        elif kind == "get":
            key = op[2]
            entry = store.get(key)
            if entry is None:
                out.append(None)
            elif not alive(entry, t):
                del store[key]
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out
